css:
.settings {
  display: grid;
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.setting {
  display: flex;
  align-items: center;
  gap: 12px;
}

.switch {
  position: relative;
  width: 44px;
  height: 24px;
  margin: 0;
  border-radius: 999px;
  background-color: #d4d4d8;
  cursor: pointer;
  appearance: none;
  transition: background-color 150ms ease;
}

.switch::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background-color: #ffffff;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.3);
  transition: transform 150ms ease;
}

.switch:checked {
  background-color: #f97316;
}

.switch:checked::before {
  transform: translateX(20px);
}

.switch:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.state {
  width: 24px;
  color: #71717a;
  font-size: 12px;
}

.state::before {
  content: "Off";
}

.switch:checked + .state::before {
  content: "On";
  color: #c2410c;
}
